window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[350]={"id":"350","numero":350,"titre":"Grosse jambe rouge aiguë","objectifs":[{"id":"350-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la grosse jambe rouge aiguë","contenu":"<p>La <span class=\"kw-def\">grosse jambe rouge aiguë</span> est un <strong>syndrome clinique</strong> — pas un diagnostic — défini par l'association d'un <span class=\"kw-clinique\">placard érythémateux</span> et d'un <span class=\"kw-clinique\">œdème</span> d'un membre inférieur, d'<span class=\"kw-clinique\">installation aiguë</span>, le plus souvent <strong>unilatéral</strong>. Sa reconnaissance impose deux réflexes : <span class=\"kw-etio\">identifier l'étiologie</span> (de loin l'<span class=\"kw-etio\">érysipèle</span>) et <span class=\"kw-alerte\">ne pas méconnaître l'urgence</span> (<span class=\"kw-alerte\">fasciite nécrosante</span>).</p>\n      <p><strong>Tableau typique</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre</span> <span class=\"kw-chiffre\">≥ 38 °C</span> + signes <span class=\"kw-etio\">infectieux</span></li>\n        <li><span class=\"kw-clinique\">Placard érythémateux bien limité</span>, parfois extensif, associé à un <span class=\"kw-clinique\">œdème</span>, généralement <strong>unilatéral</strong></li>\n        <li><span class=\"kw-clinique\">Installation rapide</span> en quelques <span class=\"kw-chiffre\">heures</span> voire quelques <span class=\"kw-chiffre\">jours</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Un cadre, pas une maladie.</strong> « Grosse jambe rouge aiguë » regroupe des causes <span class=\"kw-etio\">infectieuses</span> (<span class=\"kw-clinique\">érysipèle</span>, dermohypodermite nécrosante) et <span class=\"kw-etio\">non infectieuses</span> (insuffisance veineuse, <span class=\"kw-clinique\">eczéma</span>, TVP…). La démarche clinique tranche entre elles selon la <span class=\"kw-clinique\">fièvre</span>, la <span class=\"kw-clinique\">cinétique</span> et la présence de <span class=\"kw-alerte\">signes de gravité</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 155 — Infection cutanéo-muqueuse · 349 — Infection des parties molles</em></p>","frequence":0},{"id":"350-2","rang":"A","rubrique":"Définition","titre":"Connaître les principales étiologies de la grosse jambe rouge aiguë","contenu":"<p><span class=\"kw-clinique\">Les</span> étiologies se hiérarchisent selon leur <span class=\"kw-clinique\">typicité</span>. L'<span class=\"kw-etio\">érysipèle</span> domine très largement ; la <span class=\"kw-alerte\">dermohypodermite / fasciite nécrosante</span> est rare mais à évoquer systématiquement car elle engage le <span class=\"kw-alerte\">pronostic vital</span>.</p>\n      <table >\n        <thead><tr><th>Cadre</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Tableaux typiques</strong></span></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Érysipèle</span> :</strong> <span class=\"kw-etio\">cause la plus fréquente de loin</span>, diagnostic généralement facile<br>\n              <strong>Dermohypodermite <span class=\"kw-etio\">bactérienne</span> nécrosante / <span class=\"kw-alerte\">fasciite nécrosante</span> :</strong> <span class=\"kw-alerte\">urgence vitale</span> à <span class=\"kw-ci\">ne jamais</span> manquer\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Tableaux moins typiques</strong></span></td>\n            <td>\n              <strong>Insuffisance veineuse chronique :</strong> dermohypodermite <span class=\"kw-etio\">inflammatoire</span> (la répétition aboutit à la <span class=\"kw-clinique\">lipodermatosclérose</span>)<br>\n              <strong><span class=\"kw-clinique\">Eczéma</span> :</strong> <span class=\"kw-ci\">allergie</span> de <span class=\"kw-def\">contact</span> ou dermite de stase ; <span class=\"kw-clinique\">prurit</span>, vésicules, bords émiettés<br>\n              <strong>Pied diabétique :</strong> dermohypodermite sur <span class=\"kw-clinique\">trouble trophique</span><br>\n              <strong>Autres DHB aiguës :</strong> <span class=\"kw-etio\">pasteurellose</span> (morsure), <span class=\"kw-etio\">rouget du porc</span> (érysipéloïde)<br>\n              <strong>Syndrome des loges</strong><br>\n              <strong>Formes trompeuses :</strong> <span class=\"kw-clinique\">érysipèle</span> atypique (subaigu), DHB de l'<span class=\"kw-clinique\">immunodéprimé</span> (peu inflammatoire)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Diagnostics différentiels</strong></span> (hors DHB)</td>\n            <td>\n              <strong>Inflammatoires :</strong> <span class=\"kw-etio\">érythème noueux</span> (nodules) ; <span class=\"kw-etio\">panniculite</span><br>\n              <strong>Vasculaires :</strong> <span class=\"kw-etio\">TVP isolée</span> (ne donne pas de grosse jambe rouge) ; <span class=\"kw-alerte\">ischémie artérielle aiguë</span> (ni <span class=\"kw-clinique\">érythème</span> ni <span class=\"kw-clinique\">œdème</span>)<br>\n              <strong>Autres :</strong> <span class=\"kw-clinique\">lymphangite</span> ; <span class=\"kw-etio\">borréliose</span> (érythème migrant, non fébrile) ; <span class=\"kw-clinique\">lymphœdème chronique</span> en <span class=\"kw-clinique\">poussée</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 155 — Infection cutanéo-muqueuse · 226 — Thrombose veineuse profonde - EP · 225 — Artériopathie oblitérante - anévrysme</em></p>","frequence":1},{"id":"350-3","rang":"A","rubrique":"Etiologies","titre":"Connaître la principale cause de grosse jambe rouge aiguë fébrile","contenu":"<p>La principale cause de grosse jambe rouge aiguë fébrile est l'<strong><span class=\"kw-def\">érysipèle</span></strong> ⭐⭐⭐⭐ : c'est le <span class=\"kw-alerte\">1ᵉʳ diagnostic à évoquer</span>. Il s'agit d'une <span class=\"kw-def\">dermohypodermite bactérienne aiguë non nécrosante</span> localisée, dont la symptomatologie bruyante contraste avec une prolifération <span class=\"kw-etio\">bactérienne</span> paradoxalement peu intense (phénomène de <span class=\"kw-def\">super-antigène</span>, <span class=\"kw-bio\">hémocultures</span> positives dans <span class=\"kw-chiffre\">&lt; 5 %</span> des cas).</p>\n      <table >\n        <thead><tr><th>Item</th><th>À retenir</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\"><strong>Germe</strong></span></td><td><span class=\"kw-etio\">Streptococcus pyogenes</span> (<strong>SGA, β-hémolytique du groupe A</strong>) = <strong>principal ++</strong> ; plus rarement strepto B / C / G ou <span class=\"kw-etio\">S. aureus</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Terrain</strong></span></td><td>adulte <span class=\"kw-chiffre\">&gt; 40 ans</span>, âge moyen <span class=\"kw-chiffre\">60 ans</span> ; chez l'<span class=\"kw-clinique\">enfant</span>, FR principal = <span class=\"kw-etio\">varicelle</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Facteurs favorisants</strong></span></td><td><span class=\"kw-etio\">ATCD d'érysipèle</span> ; <span class=\"kw-clinique\">obésité</span> (IMC &gt; 30) ; <span class=\"kw-clinique\">œdème chronique / lymphœdème</span> ; <span class=\"kw-clinique\">porte d'entrée cutanée</span> (intertrigo inter-orteils, ulcère, plaie)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Porte d'entrée</strong></span></td><td>retrouvée dans <span class=\"kw-chiffre\">3/4 des cas</span> — à chercher systématiquement</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Tableau clinique</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre ± frissons</span> élevée (<span class=\"kw-chiffre\">39-40 °C</span>), début <strong>brutal</strong>, <span class=\"kw-clinique\">précède souvent de quelques heures</span> <span class=\"kw-clinique\">les</span> lésions</li>\n        <li><span class=\"kw-clinique\">Placard inflammatoire</span> rouge, chaud, œdémateux, douloureux : extension rapide, <strong>unilatéral</strong> (<span class=\"kw-imagerie\">marquer les contours au feutre ++</span>)</li>\n        <li><span class=\"kw-clinique\">Adénopathie satellite</span> et <span class=\"kw-clinique\">lymphangite</span> : inconstantes mais fréquentes</li>\n        <li>Signes possibles <strong>non graves</strong> : <span class=\"kw-clinique\">bourrelet périphérique</span> (surtout au visage), <span class=\"kw-clinique\">décollement bulleux superficiel</span>, <span class=\"kw-clinique\">purpura localisé</span> sur le <span class=\"kw-clinique\">placard</span></li>\n      </ul>\n      <p><strong>Localisations</strong> : membres inférieurs <span class=\"kw-chiffre\">90 %</span> ; visage <span class=\"kw-chiffre\">5-10 %</span> (<span class=\"kw-alerte\">staphylococcie maligne de la face</span> si <span class=\"kw-etio\">S. aureus</span>) ; membre supérieur après <span class=\"kw-ttt\">curage ganglionnaire</span> ; thorax après thoracotomie.</p>\n      <p><strong>Complications</strong> : locales (<span class=\"kw-clinique\">abcès</span>, <span class=\"kw-chiffre\">5-10 %</span>) ; systémiques rares (<span class=\"kw-chiffre\">&lt; 5 %</span> : <span class=\"kw-clinique\">septicémie</span>, <span class=\"kw-bio\">glomérulonéphrite aiguë post-streptococcique</span>) ; <span class=\"kw-alerte\">récidive</span> = complication la plus fréquente (<span class=\"kw-chiffre\">20-30 %</span>, sur persistance des FR).</p>\n      <div class=\"callout callout-warn\"><strong>Signe négatif capital.</strong> Dans l'<span class=\"kw-clinique\">érysipèle</span>, <strong>pas</strong> de <span class=\"kw-alerte\">signes de gravité</span> de <span class=\"kw-alerte\">sepsis</span>, <strong>pas</strong> de <span class=\"kw-alerte\">nécrose</span> : leur présence doit faire suspecter une <span class=\"kw-alerte\">dermohypodermite nécrosante</span>. Bourrelet, décollement bulleux et <span class=\"kw-clinique\">purpura</span> localisé ne sont <strong>pas</strong> des <span class=\"kw-alerte\">signes de gravité</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectif « algorithme diagnostique » · objectif « attitude et PEC dans <span class=\"kw-clinique\">les</span> situations d'<span class=\"kw-alerte\">urgence</span> » · 155 — Infection cutanéo-muqueuse</em></p>","frequence":4},{"id":"350-4","rang":"B","rubrique":"Etiologies","titre":"Connaître les autres étiologies de grosse jambe rouge aiguë","contenu":"<p>Au-delà de l'<span class=\"kw-clinique\">érysipèle</span> et de la <span class=\"kw-alerte\">fasciite nécrosante</span>, plusieurs étiologies — <span class=\"kw-etio\">infectieuses</span>, <span class=\"kw-etio\">veineuses</span> ou <span class=\"kw-etio\">inflammatoires</span> — peuvent réaliser une grosse jambe rouge aiguë ou en imposer.</p>\n      <h4 class=\"kw-def\">1 · Autres dermohypodermites bactériennes</h4>\n      <table >\n        <thead><tr><th>Entité</th><th>Contexte / clinique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Pasteurellose</strong></span></td><td><span class=\"kw-etio\">Pasteurella multocida</span> après <span class=\"kw-clinique\">morsure animale</span> (chat, chien) — inoculation</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Rouget du porc</strong></span> (érysipéloïde)</td><td><span class=\"kw-etio\">Erysipelothrix rhusiopathiae</span> : plaie érythémateuse de la <span class=\"kw-clinique\">main</span>, pourtour œdématié, <span class=\"kw-clinique\">extrêmement douloureuse</span>, après blessure par un <strong>os d'origine animale</strong> (bouchers)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Pied diabétique</strong></span></td><td>dermohypodermite sur <span class=\"kw-clinique\">trouble trophique</span> du diabétique</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Formes trompeuses</strong></span></td><td><span class=\"kw-clinique\">érysipèle</span> atypique (subaigu, <span class=\"kw-clinique\">fièvre</span>/hyperleucocytose modérées) ; DHB de l'<span class=\"kw-clinique\">immunodéprimé</span> (peu de signes inflammatoires)</td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"kw-def\">2 · Causes veineuses / inflammatoires chroniques</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Dermohypodermite inflammatoire</span> sur <span class=\"kw-clinique\">insuffisance veineuse chronique</span> (répétition → <span class=\"kw-clinique\">lipodermatosclérose</span>, guêtre rétractile)</li>\n        <li><span class=\"kw-etio\">Eczéma</span> : <span class=\"kw-ci\">allergie</span> de <span class=\"kw-def\">contact</span> ou dermite de stase — <span class=\"kw-clinique\">prurit</span>, vésicules sur placards à bords émiettés</li>\n        <li><span class=\"kw-alerte\">Syndrome des loges</span></li>\n      </ul>\n      <h4 class=\"kw-def\">3 · Diagnostics différentiels (non dermohypodermites)</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Érythème noueux</span> : nodules des membres inférieurs ; <span class=\"kw-etio\">panniculite</span> (cuisses, abdomen, bras, ± signes systémiques)</li>\n        <li><span class=\"kw-etio\">TVP isolée</span> : ne donne <strong>pas</strong> de grosse jambe rouge, mais peut s'associer à un <span class=\"kw-clinique\">érysipèle</span> (<span class=\"kw-imagerie\">écho-doppler veineux</span> si doute)</li>\n        <li><span class=\"kw-alerte\">Ischémie artérielle aiguë</span> : <span class=\"kw-clinique\">nécroses cutanées</span>, <strong>pas d'<span class=\"kw-clinique\">érythème</span> ni d'<span class=\"kw-clinique\">œdème</span></strong></li>\n        <li><span class=\"kw-clinique\">Lymphangite</span> ; <span class=\"kw-etio\">borréliose</span> (<span class=\"kw-clinique\">érythème</span> annulaire centrifuge, non fébrile, peu <span class=\"kw-etio\">inflammatoire</span>) ; <span class=\"kw-clinique\">lymphœdème chronique</span> en <span class=\"kw-clinique\">poussée</span> inflammatoire (DD difficile si unilatéral)</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — Thrombose veineuse profonde - EP · 225 — Artériopathie oblitérante - anévrysme · 155 — Infection cutanéo-muqueuse</em></p>","frequence":0},{"id":"350-5","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître la pertinence des examens complémentaires (de l’érysipèle) dans un contexte de grosse jambe rouge (selon les caractéristiques cliniques et l’orientation diagnostique)","contenu":"<p>Le diagnostic d'<span class=\"kw-clinique\">érysipèle</span> est <strong>clinique</strong> : la prescription d'examens dépend de la <span class=\"kw-clinique\">typicité</span> et des <span class=\"kw-alerte\">signes de gravité</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Aucun examen en forme typique.</strong> Dans l'<span class=\"kw-clinique\">érysipèle</span> typique non compliqué, <span class=\"kw-clinique\">les</span> examens complémentaires sont <strong>inutiles</strong> ❌ ; dans les tableaux atypiques leur intérêt reste limité (faible <span class=\"kw-bio\">sensibilité</span> et <span class=\"kw-bio\">spécificité</span>) — <strong>la clinique prime</strong>.</div>\n      <table >\n        <thead><tr><th>Domaine</th><th>Indication / résultats</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Biologie</strong></span></td>\n            <td>\n              <strong>Usuelle :</strong> <span class=\"kw-bio\">hyperPNN</span>, <span class=\"kw-bio\">syndrome inflammatoire</span> (<span class=\"kw-bio\">CRP</span>)<br>\n              <strong>Si <span class=\"kw-alerte\">signes de gravité</span> 🔥 :</strong> <span class=\"kw-bio\">ionogramme</span> ; <span class=\"kw-bio\">créatininémie</span> ; <span class=\"kw-bio\">enzymes musculaires (CPK)</span> ; <span class=\"kw-bio\">gaz du sang / pH</span> (acidose métabolique ?) ; <span class=\"kw-bio\">hémostase</span> (<span class=\"kw-alerte\">CIVD</span> ?)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Microbiologie</strong></span></td>\n            <td>\n              <strong><span class=\"kw-bio\">Hémocultures</span> :</strong> faible rentabilité (<span class=\"kw-chiffre\">&lt; 5 %</span> positives)<br>\n              <strong>Prélèvement de <span class=\"kw-clinique\">porte d'entrée</span> :</strong> utile dans <span class=\"kw-clinique\">les</span> formes graves, mais interprétation délicate (<span class=\"kw-etio\">colonisation</span> par des <span class=\"kw-bio\">BGN</span> non responsables)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>Selon le contexte</strong></span></td>\n            <td>\n              <strong>Suspicion de TVP :</strong> <span class=\"kw-imagerie\">écho-doppler veineux</span> + <span class=\"kw-bio\">D-dimères</span><br>\n              <strong>Suspicion de DHB nécrosante :</strong> <span class=\"kw-imagerie\">échographie des parties molles</span>, <span class=\"kw-imagerie\">IRM</span> — sans délai mais sans retarder la PEC\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Indications d'un prélèvement microbiologique</strong> : <span class=\"kw-clinique\">morsure</span> animale/humaine, plaie post-traumatique, <span class=\"kw-clinique\">voyage</span> ou survenue en <span class=\"kw-clinique\">milieu aquatique</span>, <span class=\"kw-clinique\">immunodéprimé</span>, forme nosocomiale, <span class=\"kw-alerte\">signes de gravité</span> locaux ou généraux.</p>\n      <div class=\"callout callout-info\"><strong>Piège des <span class=\"kw-bio\">D-dimères</span>.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-bio\">D-dimères</span> sont également <span class=\"kw-clinique\">élevés</span> dans une dermohypodermite infectieuse : ils ne permettent pas à eux seuls d'écarter ou d'affirmer une TVP — l'<span class=\"kw-imagerie\">écho-doppler</span> tranche.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — Thrombose veineuse profonde - EP</em></p>","frequence":0},{"id":"350-6","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’un érysipèle de jambe typique","contenu":"<p>L'<span class=\"kw-def\">érysipèle</span> de jambe typique réalise un <span class=\"kw-clinique\">placard inflammatoire</span> caractéristique, reconnaissable au premier coup d'œil ⭐.</p>\n      <p><strong>Sémiologie de l'image</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Placard érythémateux rouge vif</span>, <span class=\"kw-clinique\">chaud</span>, <strong>bien limité</strong>, <span class=\"kw-clinique\">œdémateux</span> et <span class=\"kw-clinique\">douloureux</span></li>\n        <li>Atteinte <strong>unilatérale</strong> d'un <span class=\"kw-clinique\">membre inférieur</span>, à <span class=\"kw-clinique\">extension rapide</span> (contours marqués au feutre pour suivre l'<span class=\"kw-clinique\">évolution</span>)</li>\n        <li>Possibles (non graves) : <span class=\"kw-clinique\">bourrelet périphérique</span> (limite nette surélevée, surtout au visage), <span class=\"kw-clinique\">décollement bulleux superficiel</span>, <span class=\"kw-clinique\">purpura localisé</span> sur le <span class=\"kw-clinique\">placard</span></li>\n        <li>Souvent, <span class=\"kw-clinique\">porte d'entrée</span> visible en aval (<span class=\"kw-etio\">intertrigo inter-orteils</span>, <span class=\"kw-etio\">ulcère</span>)</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Ce qu'une photo ne doit PAS montrer dans un <span class=\"kw-clinique\">érysipèle</span> simple.</strong> <span class=\"kw-alerte\">Nécrose</span> (<span class=\"kw-alerte\">plaques noirâtres</span>, <span class=\"kw-alerte\">zones livedoïdes</span>), <span class=\"kw-alerte\">bulles hémorragiques</span>, <span class=\"kw-alerte\">taches cyaniques</span> ou <span class=\"kw-alerte\">livedo</span> font basculer vers une <span class=\"kw-alerte\">dermohypodermite nécrosante</span>.</div>\n      <!-- TODO Kevin : déposer photo-erysipele-jambe-typique.jpg dans assets/images/350/ puis remplacer ce callout par le bloc <figure class=\"obj-figure\"> (aucune image clinique disponible dans fiches sources/350/ ni dans IMAGERIE A CONNAITRE.pdf, qui est radiologique). -->\n      <div class=\"callout callout-warn\"><strong>Image à ajouter.</strong> Aucune photographie clinique n'est disponible dans <span class=\"kw-clinique\">les</span> sources du dossier <code>350/</code>. Kevin déposera une photo d'<span class=\"kw-clinique\">érysipèle</span> de jambe typique dans <code>assets/images/350/</code> ; la transcription sémiologique ci-dessus reste valable en attendant.</div>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectif « principale cause de grosse jambe rouge aiguë fébrile » · 155 — Infection cutanéo-muqueuse</em></p>","frequence":1},{"id":"350-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l’algorithme diagnostique","contenu":"<p>Devant une grosse jambe rouge, l'algorithme s'articule sur deux questions : <span class=\"kw-clinique\">y a-t-il de la fièvre</span> ? et <span class=\"kw-clinique\">l'évolution est-elle aiguë</span> ? — avec recherche de <span class=\"kw-alerte\">signes de gravité</span> d'emblée.</p>\n      <h4 class=\"kw-def\">Algorithme dermatologique</h4>\n      <table >\n        <thead><tr><th>Présentation</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Aiguë fébrile</strong></span> + dermohypodermite</td><td><span class=\"kw-etio\">Érysipèle</span><br>autres DH infectieuses<br><span class=\"kw-alerte\">fasciite nécrosante</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Subaiguë</strong></span></td><td><strong>Fébrile :</strong> DH infectieuses<br><strong>Non fébrile :</strong> <span class=\"kw-etio\">insuffisance veineuse</span>, <span class=\"kw-etio\">pied diabétique</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Non fébrile</strong></span> + autres lésions élémentaires</td><td><span class=\"kw-etio\">Eczéma</span></td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"kw-def\">Algorithme par contexte (Pilly)</h4>\n      <ul>\n        <li><strong>Matériel d'<span class=\"kw-ttt\">ostéosynthèse</span>, prothèse, pied diabétique</strong> → évoquer une <span class=\"kw-alerte\">infection ostéo-articulaire</span> : <span class=\"kw-ttt\">avis chirurgical en urgence</span></li>\n        <li><strong>Morsure / griffure</strong> → infections staphylococciques / streptococciques, <span class=\"kw-etio\">maladies d'inoculation</span> (pasteurellose), souvent plurimicrobiennes : évaluer la <span class=\"kw-clinique\">profondeur</span> et le risque pour <span class=\"kw-clinique\">les</span> structures nobles, <span class=\"kw-ttt\">parage chirurgical</span> si besoin, évaluer le <span class=\"kw-alerte\">risque rabique</span></li>\n        <li><strong>Dermohypodermite</strong> → <span class=\"kw-etio\">érysipèle</span> ; forme nécrosante (<span class=\"kw-alerte\">douleur, sepsis, nécrose</span>) = <span class=\"kw-alerte\">urgence médico-chirurgicale</span></li>\n        <li><strong>Diagnostics différentiels</strong> : dermite de stase, <span class=\"kw-etio\">TVP</span>, <span class=\"kw-clinique\">eczéma</span>, syndrome des loges, hématome, lymphœdème chronique, pied de Charcot</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Le réflexe.</strong> Toute grosse jambe rouge <span class=\"kw-clinique\">aiguë fébrile</span> = <span class=\"kw-etio\">érysipèle</span> jusqu'à preuve du contraire — mais on cherche d'abord <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">signes de gravité</span> qui signent une forme nécrosante.</div>\n      <!-- TODO Kevin : un schéma « Orientation diagnostique devant une grosse jambe rouge » existe dans la fiche Notion liée ; le déposer en image dans assets/images/350/ si souhaité (jamais de SVG redessiné). -->\n      <p class=\"obj-renvois\"><em>📎 Items liés : 349 — Infection des parties molles · 155 — Infection cutanéo-muqueuse</em></p>","frequence":0},{"id":"350-8","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître l’attitude et la prise en charge clinique dans les situations d’urgence","contenu":"<p>La prise en charge dépend de la <span class=\"kw-clinique\">gravité</span> : ambulatoire et médicale pour l'<span class=\"kw-clinique\">érysipèle</span> simple, <span class=\"kw-alerte\">médico-chirurgicale en réanimation</span> pour la forme nécrosante.</p>\n      <h4 class=\"kw-def\">1 · Orientation & critères d'<span class=\"kw-alerte\">hospitalisation</span></h4>\n      <p>L'<span class=\"kw-alerte\">hospitalisation</span> s'impose si un <span class=\"kw-ttt\">traitement parentéral</span> et/ou une <span class=\"kw-clinique\">surveillance rapprochée</span> sont nécessaires :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Doute diagnostique</span> ; <span class=\"kw-alerte\">signes locaux et/ou généraux marqués</span> ; risque de complications</li>\n        <li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-clinique\">âge &gt; 75 ans</span> ou <span class=\"kw-clinique\">&lt; 1 an</span>, <span class=\"kw-etio\">obésité</span> morbide, <span class=\"kw-def\">comorbidités</span> à risque de <span class=\"kw-alerte\">décompensation</span></li>\n        <li>Contexte social rendant repos et <span class=\"kw-def\">suivi</span> difficiles en ambulatoire</li>\n        <li><span class=\"kw-alerte\">Absence d'amélioration à 24-72 h</span> ou <span class=\"kw-alerte\">extension sous traitement</span> (feutre ++)</li>\n      </ul>\n      <h4 class=\"kw-def\">2 · Mesures générales (communes)</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Repos au lit</span>, jambe <strong>surélevée</strong> jusqu'à régression des signes inflammatoires (↓ <span class=\"kw-clinique\">œdème</span> et douleur)</li>\n        <li><span class=\"kw-ttt\">Antalgiques</span> (<span class=\"kw-ttt\">paracétamol</span>) — <span class=\"kw-ci\">pas d'AINS</span> ❌, <span class=\"kw-ci\">pas de corticoïdes</span> ❌</li>\n        <li><span class=\"kw-ttt\">Anticoagulation préventive</span> (<span class=\"kw-ttt\">HBPM</span> / <span class=\"kw-ttt\">héparine</span> calcique) <strong>uniquement si FR de MTEV</strong></li>\n        <li><span class=\"kw-ttt\">Vaccination antitétanique</span> à vérifier et mettre à jour ; traitement de la <span class=\"kw-clinique\">porte d'entrée</span></li>\n      </ul>\n      <h4 class=\"kw-def\">3 · <span class=\"kw-ttt\">Antibiothérapie</span> de l'<span class=\"kw-clinique\">érysipèle</span></h4>\n      <ul>\n        <li>1ʳᵉ intention : <span class=\"kw-ttt\">amoxicilline</span> <span class=\"kw-chiffre\">7 jours</span> — voie <strong>per os</strong> si ambulatoire, <strong>IV</strong> si <span class=\"kw-alerte\">hospitalisation</span> (puis relais PO) ; <span class=\"kw-alerte\">posologie adaptée au poids</span> (risque de sous-dosage / échec)</li>\n        <li><span class=\"kw-ci\">Allergie</span> à la pénicilline : <span class=\"kw-ttt\">pristinamycine</span> ou <span class=\"kw-ttt\">clindamycine</span></li>\n        <li>Pédiatrie : <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> ; morsure animale : <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> <span class=\"kw-chiffre\">7 j</span></li>\n        <li><span class=\"kw-ci\">Pas d'antibiothérapie locale</span> ❌</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> vitale = dermohypodermite / <span class=\"kw-alerte\">fasciite nécrosante</span></strong> (<span class=\"kw-alerte\">≈ 30 % de mortalité</span>). Triple front : <strong><span class=\"kw-alerte\">réanimation</span></strong> (<span class=\"kw-alerte\">USI</span>, défaillances d'organe), <strong><span class=\"kw-ttt\">chirurgie</span> précoce</strong> (mise à plat, excision des tissus nécrosés, reprises quotidiennes), <span class=\"kw-ttt\">antibiothérapie IV forte dose</span> <span class=\"kw-chiffre\">14-21 j</span>. <span class=\"kw-ci\">Arrêt des AINS</span> ❌. <span class=\"kw-alerte\">L'imagerie ne doit JAMAIS retarder la chirurgie.</span></div>\n      <table >\n        <thead><tr><th>Forme de <span class=\"kw-clinique\">fasciite</span></th><th><span class=\"kw-ttt\">Antibiothérapie</span> IV</th></tr></thead>\n        <tbody>\n          <tr><td>Membres / cervico-faciale</td><td><span class=\"kw-ttt\">Augmentin + clindamycine</span></td></tr>\n          <tr><td>Abdomino-périnéale</td><td><span class=\"kw-ttt\">pipéracilline-tazobactam</span> ou <span class=\"kw-ttt\">imipénème</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Gangrène</span> de Fournier</td><td><span class=\"kw-ttt\">pénicilline + métronidazole + aminoside</span></td></tr>\n          <tr><td>Toxicomane IV</td><td><span class=\"kw-ttt\">Augmentin / pénicilline M ± vancomycine</span> (anti-<span class=\"kw-bio\">SARM</span>)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span> · 349 — Infection des parties molles</em></p>","frequence":0},{"id":"350-9","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir évoquer le diagnostic d’une fasciite nécrosante","contenu":"<p>La <span class=\"kw-alerte\">dermohypodermite bactérienne nécrosante / fasciite nécrosante</span> est <span class=\"kw-chiffre\">100 fois plus rare</span> que l'<span class=\"kw-clinique\">érysipèle</span> mais réalise une <span class=\"kw-alerte\">urgence vitale médico-chirurgicale</span>. Principe : <strong>présentation = <span class=\"kw-clinique\">érysipèle</span> + éléments de gravité</strong> ; la <span class=\"kw-clinique\">nécrose</span> évolue de la <span class=\"kw-clinique\">profondeur vers la superficie</span>, d'où des signes cutanés parfois retardés. Germe : <span class=\"kw-etio\">SGA</span>, <span class=\"kw-bio\">polymicrobien</span> dans <span class=\"kw-chiffre\">70-80 %</span> (+ S. aureus), souches parfois productrices de <span class=\"kw-alerte\">toxines</span> (<span class=\"kw-alerte\">choc</span> toxinique).</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeaux rouges</span> — signes locaux.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Douleur spontanée intense</span> qui dépasse <span class=\"kw-clinique\">les</span> zones inflammatoires, <strong>non soulagée par les <span class=\"kw-ttt\">antalgiques</span> de palier 1-2</strong></li>\n          <li><span class=\"kw-alerte\">Nécrose</span> : pâleur, plaques noirâtres, zones livedoïdes, taches cyaniques</li>\n          <li><span class=\"kw-alerte\">Bulles hémorragiques / séro-hématiques</span> ; écoulements fétides</li>\n          <li><span class=\"kw-alerte\">Hypoesthésie</span> voire anesthésie (anesthésie douloureuse), <span class=\"kw-alerte\">crépitation</span> (<span class=\"kw-etio\">anaérobies</span>)</li>\n          <li><span class=\"kw-alerte\">Extension rapide malgré une antibiothérapie bien conduite</span> ; induration au-delà de l'<span class=\"kw-clinique\">érythème</span></li>\n        </ul>\n      </div>\n      <div class=\"callout callout-danger\"><strong>Signes généraux — <span class=\"kw-alerte\">sepsis</span>.</strong> <span class=\"kw-clinique\">Fièvre</span> élevée ou <span class=\"kw-alerte\">hypothermie</span>, <span class=\"kw-clinique\">frissons</span>, <span class=\"kw-alerte\">confusion / désorientation</span>, <span class=\"kw-clinique\">tachypnée</span>, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-alerte\">hypotension</span>, oligurie, pâleur. <strong><span class=\"kw-chiffre\">qSOFA</span> <span class=\"kw-chiffre\">≥ 2</span></strong> : FR <span class=\"kw-chiffre\">≥ 22/min</span> ; PAS <span class=\"kw-chiffre\">≤ 100 mmHg</span> ; <span class=\"kw-clinique\">Glasgow &lt; 15</span>.</div>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-clinique\">Érysipèle</span></th><th><span class=\"kw-alerte\">Fasciite nécrosante</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Douleur</strong></td><td>modérée, localisée au <span class=\"kw-clinique\">placard</span></td><td><span class=\"kw-alerte\">intense, dépasse l'érythème, résistante aux antalgiques</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Nécrose</span> / <span class=\"kw-clinique\">livedo</span></strong></td><td>absente</td><td><span class=\"kw-alerte\">présente</span> (signe la <span class=\"kw-clinique\">nécrose</span>)</td></tr>\n          <tr><td><strong>Signes généraux</strong></td><td><span class=\"kw-clinique\">fièvre</span> isolée</td><td><span class=\"kw-alerte\">sepsis (qSOFA ≥ 2)</span></td></tr>\n          <tr><td><strong>FR spécifiques</strong></td><td>ATCD <span class=\"kw-clinique\">érysipèle</span>, lymphœdème, intertrigo</td><td><span class=\"kw-etio\">âge &gt; 60 ans</span>, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">immunodépression</span>, toxicomanie IV, AOMI, <span class=\"kw-etio\">AINS</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Faux amis.</strong> <span class=\"kw-clinique\">Phlyctène</span>, <span class=\"kw-clinique\">décollement bulleux</span> et <span class=\"kw-clinique\">purpura</span> ne sont <strong>pas</strong> des <span class=\"kw-alerte\">signes de gravité</span> ⭐ : ils peuvent exister dans l'<span class=\"kw-clinique\">érysipèle</span> non compliqué. Ce qui inquiète : <span class=\"kw-clinique\">nécrose</span>, douleur disproportionnée, <span class=\"kw-alerte\">sepsis</span>, extension sous ATB.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span> · 349 — Infection des parties molles</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Niveau :</strong> la <span class=\"kw-alerte\">dermohypodermite / fasciite nécrosante</span> est une <span class=\"kw-alerte\">urgence médico-chirurgicale</span> à <span class=\"kw-alerte\">pronostic vital</span> ; l'<span class=\"kw-etio\">érysipèle</span> typique relève le plus souvent d'une PEC <span class=\"kw-ttt\">ambulatoire</span>.<br><strong>1ᵉʳ réflexe :</strong> devant toute grosse jambe rouge aiguë, <span class=\"kw-alerte\">rechercher d'emblée les signes de gravité</span> avant tout.<br><strong>Fenêtre :</strong> en cas de suspicion de DHB nécrosante, <span class=\"kw-imagerie\">imagerie sans délai</span> (<span class=\"kw-imagerie\">échographie des parties molles</span>, <span class=\"kw-imagerie\">IRM</span>).<br><strong>1ᵉʳ geste :</strong> <span class=\"kw-ttt\">avis chirurgical en urgence</span> si <span class=\"kw-alerte\">forme nécrosante</span> ou <span class=\"kw-etio\">infection ostéo-articulaire</span> suspectée (matériel, prothèse, pied diabétique).</p>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-etio\">érysipèle</span> typique sans <span class=\"kw-alerte\">signe de gravité</span>, lorsque ni <span class=\"kw-ttt\">traitement parentéral</span> ni <span class=\"kw-clinique\">surveillance rapprochée</span> ne sont nécessaires.<br><strong><span class=\"kw-alerte\">Hospitalisation</span></strong> si <span class=\"kw-ttt\">traitement parentéral</span> et/ou <span class=\"kw-clinique\">surveillance rapprochée</span> requis, en particulier : <span class=\"kw-clinique\">doute diagnostique</span> ; <span class=\"kw-alerte\">signes locaux et/ou généraux marqués</span> ; <span class=\"kw-alerte\">risque de complications locales</span> ; <span class=\"kw-clinique\">comorbidité</span> ; <span class=\"kw-clinique\">contexte social</span> rendant repos/<span class=\"kw-def\">suivi</span> difficiles ; <span class=\"kw-alerte\">absence d'amélioration après 72 h</span> de traitement ou <span class=\"kw-alerte\">extension</span>.<br><strong><span class=\"kw-alerte\">Réanimation</span> / <span class=\"kw-ttt\">chirurgie</span> :</strong> toute <span class=\"kw-alerte\">forme nécrosante</span> ou <span class=\"kw-alerte\">sepsis sévère voire choc septique</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Douleur spontanée intense</span> (locale, disproportionnée)</li><li><span class=\"kw-alerte\">Œdème majeur</span></li><li><span class=\"kw-alerte\">Bulles hémorragiques</span></li><li><span class=\"kw-alerte\">Nécrose cutanée</span> : pâleur de certaines zones, <span class=\"kw-alerte\">plaques noirâtres</span>, <span class=\"kw-alerte\">zones livedoïdes</span>, atones</li><li><span class=\"kw-alerte\">Hypoesthésie</span> (ou à l'inverse douleurs spontanées intenses)</li><li><span class=\"kw-alerte\">Livedo</span></li><li><span class=\"kw-alerte\">Crépitation</span></li><li><span class=\"kw-alerte\">Extension des lésions malgré une antibiothérapie bien conduite</span></li><li>Signes généraux de <span class=\"kw-alerte\">sepsis</span> : <span class=\"kw-alerte\">fièvre élevée avec confusion</span>, désorientation, <span class=\"kw-clinique\">tachypnée</span>, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-alerte\">hypotension</span>, oligurie, pâleur</li><li><span class=\"kw-def\">Terrain</span> à risque : <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">obésité</span>, <span class=\"kw-clinique\">état de précarité</span></li></ul>","principes":"<p>Prise en charge commune à toute grosse jambe rouge <span class=\"kw-etio\">infectieuse</span>, déclinée selon la <span class=\"kw-alerte\">gravité</span> et le contexte.</p><p><strong>Mesures générales (communes)</strong></p><p><span class=\"kw-clinique\">Érysipèle</span> typique → ambulatoire ; critères d'<span class=\"kw-alerte\">hospitalisation</span> → <span class=\"kw-ttt\">traitement parentéral</span>.</p><ul><li><span class=\"kw-ttt\">Repos au lit, jambe surélevée</span> jusqu'à régression des <span class=\"kw-clinique\">signes inflammatoires</span> (diminue l'<span class=\"kw-clinique\">œdème</span> et la <span class=\"kw-clinique\">douleur</span>)</li><li><span class=\"kw-ttt\">Antalgiques</span> — <span class=\"kw-ci\">pas d'AINS</span> ❌</li><li><span class=\"kw-ttt\">Anticoagulation préventive</span> (<span class=\"kw-ttt\">héparine calcique</span> ou <span class=\"kw-ttt\">HBPM</span>) <strong>uniquement si <span class=\"kw-def\">facteurs de risque</span> de MTEV</strong></li><li><span class=\"kw-ttt\">Vaccination antitétanique</span> à vérifier et renouveler le cas échéant</li></ul><p><strong>Forme nécrosante (<span class=\"kw-clinique\">fasciite</span>)</strong></p><p><span class=\"kw-alerte\">Urgence médico-chirurgicale</span> — <span class=\"kw-alerte\">pronostic vital engagé</span>.</p><ul><li>Triade d'alerte : <span class=\"kw-alerte\">douleur</span>, <span class=\"kw-alerte\">sepsis</span>, <span class=\"kw-alerte\">nécrose</span></li><li><span class=\"kw-ttt\">Avis chirurgical en urgence</span> + prise en charge médico-chirurgicale</li><li><span class=\"kw-imagerie\">Imagerie sans délai</span> si doute (<span class=\"kw-imagerie\">échographie cutanée et des parties molles</span>, <span class=\"kw-imagerie\">IRM</span>)</li><li><span class=\"kw-ci\">Pas d'AINS</span> ❌</li></ul><p><strong>Contextes particuliers (algorithme Pilly)</strong></p><ul><li><span class=\"kw-clinique\">Matériel d'ostéosynthèse</span>, <span class=\"kw-clinique\">prothèse</span>, <span class=\"kw-clinique\">pied diabétique</span> → évoquer une <span class=\"kw-etio\">infection ostéo-articulaire</span> : <span class=\"kw-ttt\">avis chirurgical en urgence</span></li><li><span class=\"kw-clinique\">Morsure / griffure</span> → <span class=\"kw-etio\">maladies d'inoculation</span> (<span class=\"kw-etio\">pasteurellose</span>), souvent <span class=\"kw-etio\">plurimicrobiennes</span> avec <span class=\"kw-etio\">anaérobies</span> : évaluer la <span class=\"kw-clinique\">profondeur</span> et le risque pour <span class=\"kw-clinique\">les</span> structures nobles, <span class=\"kw-ttt\">parage chirurgical</span> si nécessaire, évaluer le <span class=\"kw-alerte\">risque rabique</span></li></ul>","suivi":"<p><strong><span class=\"kw-def\">Réévaluation</span> :</strong> contrôle de l'<span class=\"kw-clinique\">évolution</span> à <span class=\"kw-chiffre\">72 h</span> ; une <span class=\"kw-alerte\">absence d'amélioration</span> ou une <span class=\"kw-alerte\">extension des lésions malgré une antibiothérapie bien conduite</span> doit faire reconsidérer le diagnostic (<span class=\"kw-alerte\">fasciite nécrosante</span>) et conduire à l'<span class=\"kw-ttt\">hospitalisation</span>.<br><strong>Local :</strong> <span class=\"kw-ttt\">repos au lit, jambe surélevée</span> maintenu jusqu'à régression des <span class=\"kw-clinique\">signes inflammatoires</span>.<br><strong><span class=\"kw-def\">Surveillance</span> rapprochée</strong> (en <span class=\"kw-alerte\">hospitalisation</span>) des <span class=\"kw-alerte\">signes locaux</span> (<span class=\"kw-clinique\">nécrose</span>, douleur, extension) et <span class=\"kw-alerte\">généraux</span> (<span class=\"kw-alerte\">sepsis</span>).<br><strong>Biologie si gravité :</strong> <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">enzymes musculaires</span>, <span class=\"kw-bio\">gaz du sang / pH</span>, <span class=\"kw-bio\">hémostase</span> (<span class=\"kw-alerte\">CIVD</span> ?).</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Grosse jambe rouge aiguë — Placard érythémateux + œdème d'un membre, installation aiguë","detail":"<h4>CAT — Grosse jambe rouge aiguë — Éliminer la <span class=\"kw-alerte\">fasciite nécrosante</span>, reconnaître l'<span class=\"kw-clinique\">érysipèle</span>, décider de l'orientation</h4>","branches":[{"to":"q-gravite","label":"Évaluation initiale","color":"blue"}]},{"id":"q-gravite","kind":"decision","label":"Signes de gravité présents ? — Douleur intense disproportionnée · nécrose / livedo · bulles hémorragiques · hypoesthésie · crépitation · sepsis · extension sous antibiothérapie","branches":[{"to":"t-fasciite","label":"Oui","color":"red"},{"to":"q-fievre","label":"Non","color":"green"}]},{"id":"t-fasciite","kind":"terminal","label":"Suspicion de fasciite nécrosante — Urgence médico-chirurgicale","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Urgence médico-chirurgicale</span> : <span class=\"kw-alerte\">hospitalisation</span> immédiate + <span class=\"kw-ttt\">avis chirurgical en urgence</span></li><li><span class=\"kw-ttt\">Réanimation</span> si <span class=\"kw-alerte\">sepsis sévère</span> voire <span class=\"kw-alerte\">choc septique</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Imagerie sans délai</span> si doute : <span class=\"kw-imagerie\">échographie des parties molles</span>, <span class=\"kw-imagerie\">IRM</span></li><li>Bilan de gravité : <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">enzymes musculaires</span>, <span class=\"kw-bio\">gaz du sang / pH</span>, <span class=\"kw-bio\">hémostase</span> (<span class=\"kw-alerte\">CIVD</span> ?)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antibiothérapie parentérale</span> en <span class=\"kw-alerte\">urgence</span> + geste chirurgical</li><li><span class=\"kw-ci\">Pas d'AINS</span> ❌</li></ul>"},{"id":"q-fievre","kind":"decision","label":"Évolution aiguë et fièvre ? — La cinétique d'installation et la fièvre orientent l'étiologie","branches":[{"to":"q-orientation","label":"Aiguë + fébrile → érysipèle","color":"amber"},{"to":"t-veineux","label":"Subaiguë non fébrile","color":"blue"},{"to":"t-eczema","label":"Non fébrile + lésions élémentaires","color":"green"}]},{"id":"q-orientation","kind":"decision","label":"Critère d'hospitalisation présent ? — Doute dg · signes locaux/généraux marqués · risque de complications · comorbidité · contexte social · échec à 72 h ou extension","branches":[{"to":"t-hospit","label":"Oui (≥ 1 critère)","color":"amber"},{"to":"t-ambu","label":"Non","color":"green"}]},{"id":"t-hospit","kind":"terminal","label":"Hospitalisation — érysipèle / DH compliquée","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> pour <span class=\"kw-ttt\">traitement parentéral</span> et/ou <span class=\"kw-clinique\">surveillance rapprochée</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antibiothérapie parentérale</span> puis relais en cas d'amélioration</li><li>Mesures générales : <span class=\"kw-ttt\">repos jambe surélevée</span>, <span class=\"kw-ttt\">antalgiques</span> (<span class=\"kw-ci\">pas d'AINS</span>), <span class=\"kw-ttt\">HBPM</span> si FR de MTEV, <span class=\"kw-ttt\">vaccination antitétanique</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Surveillance</span> rapprochée des <span class=\"kw-alerte\">signes locaux</span> et <span class=\"kw-alerte\">généraux</span> (<span class=\"kw-alerte\">sepsis</span>, extension, <span class=\"kw-clinique\">nécrose</span>)</li></ul>"},{"id":"t-ambu","kind":"terminal","label":"Érysipèle simple — PEC ambulatoire","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antibiothérapie</span> de l'<span class=\"kw-clinique\">érysipèle</span> non compliqué</li><li><span class=\"kw-ttt\">Antalgiques</span> — <span class=\"kw-ci\">pas d'AINS</span> ❌</li><li><span class=\"kw-ttt\">Repos au lit, jambe surélevée</span> jusqu'à régression des <span class=\"kw-clinique\">signes inflammatoires</span></li><li><span class=\"kw-ttt\">Anticoagulation préventive</span> (<span class=\"kw-ttt\">HBPM</span> / <span class=\"kw-ttt\">héparine</span> calcique) <strong>seulement si FR de MTEV</strong></li><li>Vérifier et mettre à jour la <span class=\"kw-ttt\">vaccination antitétanique</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Réévaluation</span> à <span class=\"kw-chiffre\">72 h</span> : <span class=\"kw-alerte\">extension</span> ou <span class=\"kw-alerte\">non-amélioration</span> → <span class=\"kw-alerte\">hospitalisation</span></li></ul>"},{"id":"t-veineux","kind":"terminal","label":"Cause non infectieuse à évoquer — Subaiguë non fébrile","color":"blue","detail":"<h4>Conduite</h4><ul><li>Évoquer une <span class=\"kw-etio\">insuffisance veineuse chronique</span> ou un <span class=\"kw-etio\">pied diabétique</span></li><li><span class=\"kw-imagerie\">Écho-doppler veineux</span> si suspicion de <span class=\"kw-etio\">TVP</span> (<span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">D-dimères</span> sont aussi élevés dans la dermohypodermite infectieuse)</li></ul>"},{"id":"t-eczema","kind":"terminal","label":"Eczéma (dermite de stase / allergie de contact) — Non fébrile + lésions élémentaires","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Prurit</span>, vésicules sur placards érythémateux à <span class=\"kw-clinique\">bords émiettés</span>, <strong>non fébrile</strong></li></ul>"}]},"cards":[{"i":"33642e15413b","n":350,"o":"350-1","u":"Définition","t":"Connaître la définition de la grosse jambe rouge aiguë","q":"La grosse jambe rouge aiguë est-elle un diagnostic ou un syndrome ?","a":"<p>La grosse jambe rouge aiguë est un <strong>syndrome clinique</strong>, et non un diagnostic spécifique. Elle regroupe diverses étiologies, infectieuses ou non.</p>"},{"i":"6e7950a2d852","n":350,"o":"350-1","u":"Définition","t":"Connaître la définition de la grosse jambe rouge aiguë","q":"Quels sont les deux réflexes essentiels devant une grosse jambe rouge aiguë ?","a":"<p>Devant une grosse jambe rouge aiguë, les deux réflexes essentiels sont :</p><ul><li>Identifier l'<strong>étiologie</strong> (le plus souvent l'<strong>érysipèle</strong>).</li><li>Ne pas méconnaître une <strong>urgence</strong> (notamment la <strong>fasciite nécrosante</strong>).</li></ul>"},{"i":"8b27018be41e","n":350,"o":"350-1","u":"Définition","t":"Connaître la définition de la grosse jambe rouge aiguë","q":"Quelle est la définition clinique d'une grosse jambe rouge aiguë ?","a":"<p>La grosse jambe rouge aiguë est un <strong>syndrome clinique</strong> caractérisé par l'association d'un <strong>placard érythémateux</strong> et d'un <strong>œdème</strong> d'un membre inférieur, d'<strong>installation aiguë</strong> et le plus souvent unilatéral.</p>"},{"i":"e160a794a803","n":350,"o":"350-1","u":"Définition","t":"Connaître la définition de la grosse jambe rouge aiguë","q":"Quels sont les signes typiques associés à une grosse jambe rouge aiguë ?","a":"<p>Les signes typiques associés à une grosse jambe rouge aiguë incluent :</p><ul><li>Fièvre ≥ <strong>38 °C</strong> et autres signes infectieux.</li><li>Un <strong>placard érythémateux</strong> bien limité, parfois extensif.</li><li>Un <strong>œdème</strong>, généralement unilatéral.</li><li>Une installation rapide en quelques <strong>heures</strong>, voire quelques <strong>jours</strong>.</li></ul>"},{"i":"041746d06f12","n":350,"o":"350-2","u":"Définition","t":"Connaître les principales étiologies de la grosse jambe rouge aiguë","q":"Parmi les étiologies non infectieuses de grosse jambe rouge aiguë, quelles sont les causes vasculaires à considérer ?","a":"<ul><li>L'<strong>insuffisance veineuse chronique</strong>, pouvant entraîner une dermohypodermite inflammatoire et une lipodermatosclérose.</li><li>Les diagnostics différentiels à ne pas confondre avec une grosse jambe rouge aiguë sont la <strong>thrombose veineuse profonde (TVP) isolée</strong> et l'<strong>ischémie artérielle aiguë</strong>, qui ne présentent pas les mêmes caractéristiques cliniques (pas d'érythème ni d'œdème pour l'ischémie artérielle aiguë).</li></ul>"},{"i":"1bd870c725b4","n":350,"o":"350-2","u":"Définition","t":"Connaître les principales étiologies de la grosse jambe rouge aiguë","q":"Quelle est l'étiologie la plus fréquente de la grosse jambe rouge aiguë ?","a":"<p>L'étiologie la plus fréquente de la grosse jambe rouge aiguë est l'<strong>érysipèle</strong>.</p>"},{"i":"beafcc8ee920","n":350,"o":"350-2","u":"Définition","t":"Connaître les principales étiologies de la grosse jambe rouge aiguë","q":"Quelle étiologie de grosse jambe rouge aiguë, rare mais grave, doit être systématiquement évoquée ?","a":"<p>La <strong>dermohypodermite bactérienne nécrosante</strong> ou <strong>fasciite nécrosante</strong> est rare mais doit être systématiquement évoquée car elle engage le pronostic vital.</p>"},{"i":"c844b018749b","n":350,"o":"350-2","u":"Définition","t":"Connaître les principales étiologies de la grosse jambe rouge aiguë","q":"Quelles sont les autres causes de grosse jambe rouge aiguë au tableau moins typique ?","a":"<ul><li>L'<strong>eczéma</strong> (de contact ou de stase) avec prurit et vésicules.</li><li>Le <strong>pied diabétique</strong> avec dermohypodermite sur trouble trophique.</li><li>Autres dermohypodermites bactériennes aiguës spécifiques comme la <strong>pasteurellose</strong> (après morsure) ou le <strong>rouget du porc</strong> (érysipéloïde).</li><li>Le <strong>syndrome des loges</strong>.</li></ul>"},{"i":"6a2e050abc21","n":350,"o":"350-3","u":"Etiologies","t":"Connaître la principale cause de grosse jambe rouge aiguë fébrile","q":"Quel est le germe principalement responsable de l'érysipèle ?","a":"<p>Le germe principalement responsable de l'érysipèle est le <em><strong>Streptococcus pyogenes</strong></em>, également appelé <strong>SGA (Streptocoque du groupe A)</strong>.</p>"},{"i":"bd01f2155c02","n":350,"o":"350-3","u":"Etiologies","t":"Connaître la principale cause de grosse jambe rouge aiguë fébrile","q":"Quelle est la définition de l'érysipèle ?","a":"<p>L'érysipèle est une <strong>dermohypodermite bactérienne aiguë non nécrosante</strong> localisée.</p>"},{"i":"bd05bc7920cc","n":350,"o":"350-3","u":"Etiologies","t":"Connaître la principale cause de grosse jambe rouge aiguë fébrile","q":"Quels sont les principaux facteurs de risque et terrains favorisants de l'érysipèle chez l'adulte ?","a":"<ul><li>Les <strong>antécédents d'érysipèle</strong>.</li><li>L'<strong>obésité</strong> (IMC &gt; 30).</li><li>L'<strong>œdème chronique</strong> ou le <strong>lymphœdème</strong>.</li><li>La présence d'une <strong>porte d'entrée cutanée</strong> (ex: intertrigo inter-orteils, ulcère, plaie).</li></ul>"},{"i":"d35cc2285404","n":350,"o":"350-3","u":"Etiologies","t":"Connaître la principale cause de grosse jambe rouge aiguë fébrile","q":"Quelle est la principale cause de grosse jambe rouge aiguë fébrile chez l'adulte, à évoquer en premier lieu ?","a":"<p>La principale cause de grosse jambe rouge aiguë fébrile est l'<strong>érysipèle</strong>.</p>"},{"i":"e1df4111983d","n":350,"o":"350-3","u":"Etiologies","t":"Connaître la principale cause de grosse jambe rouge aiguë fébrile","q":"Quels sont les signes cliniques caractéristiques d'un érysipèle typique ?","a":"<ul><li>Une <strong>fièvre élevée</strong> (39-40 °C) avec ou sans frissons, à début brutal.</li><li>Un <strong>placard inflammatoire rouge, chaud, œdémateux et douloureux</strong>, à extension rapide et <strong>unilatéral</strong>.</li><li>Des adénopathies satellites ou une lymphangite peuvent être présentes mais sont inconstantes.</li></ul>"},{"i":"0748160ff30a","n":350,"o":"350-5","u":"Examens complémentaires","t":"Connaître la pertinence des examens complémentaires (de l’érysipèle) dans un contexte de grosse jambe rouge (selon les caractéristiques cliniques et l’orientation diagnostique)","q":"Quels examens biologiques de routine sont pertinents en cas d'érysipèle, et quand sont-ils indiqués ?","a":"<p>En forme atypique ou compliquée, s'ils ont un intérêt limité, un bilan biologique peut montrer :</p><ul><li>Une <strong>hyperleucocytose à PNN</strong> (polynucléaires neutrophiles).</li><li>Un <strong>syndrome inflammatoire</strong> (élévation de la CRP)</li></ul><p>En cas de <strong>signes de gravité</strong>, un bilan plus complet est nécessaire :</p><ul><li>Ionogramme sanguin, créatininémie</li><li>Enzymes musculaires (CPK)</li><li>Gaz du sang (recherche d'une acidose métabolique)</li><li>Bilan d'hémostase (recherche d'une CIVD)</li></ul>"},{"i":"14324b1ed17b","n":350,"o":"350-5","u":"Examens complémentaires","t":"Connaître la pertinence des examens complémentaires (de l’érysipèle) dans un contexte de grosse jambe rouge (selon les caractéristiques cliniques et l’orientation diagnostique)","q":"Dans quel contexte clinique un prélèvement microbiologique est-il indiqué pour une grosse jambe rouge aiguë ?","a":"<p>Un prélèvement microbiologique est indiqué dans les situations suivantes :</p><ul><li>Morsure animale ou humaine.</li><li>Plaie post-traumatique.</li><li>Voyage ou survenue en milieu aquatique.</li><li>Patient <strong>immunodéprimé</strong>.</li><li>Forme nosocomiale.</li><li><strong>Signes de gravité</strong> locaux ou généraux.</li></ul>"},{"i":"39ff1aaac809","n":350,"o":"350-5","u":"Examens complémentaires","t":"Connaître la pertinence des examens complémentaires (de l’érysipèle) dans un contexte de grosse jambe rouge (selon les caractéristiques cliniques et l’orientation diagnostique)","q":"Quelle est l'approche diagnostique initiale de l'érysipèle face à une grosse jambe rouge aiguë ?","a":"<p>Le diagnostic d'érysipèle est avant tout <strong>clinique</strong>. Les examens complémentaires ne sont pas nécessaires dans les formes typiques non compliquées.</p>"},{"i":"87e75a1f8588","n":350,"o":"350-5","u":"Examens complémentaires","t":"Connaître la pertinence des examens complémentaires (de l’érysipèle) dans un contexte de grosse jambe rouge (selon les caractéristiques cliniques et l’orientation diagnostique)","q":"Quand suspecter une pathologie autre qu'un érysipèle devant une grosse jambe rouge aiguë et quels sont les examens complémentaires à privilégier ?","a":"<p>Les examens d'imagerie sont indiqués selon le contexte :</p><ul><li>En cas de suspicion de <strong>thrombose veineuse profonde (TVP)</strong> : réaliser un <strong>écho-Doppler veineux</strong> et un dosage des <strong>D-dimères</strong>.</li><li>En cas de suspicion de <strong>dermohypodermite bactérienne nécrosante (DHBN)</strong> : réaliser une <strong>échographie des parties molles</strong> ou une <strong>IRM</strong>, sans délai mais sans retarder la prise en charge chirurgicale.</li></ul>"},{"i":"8e8d7a38259d","n":350,"o":"350-5","u":"Examens complémentaires","t":"Connaître la pertinence des examens complémentaires (de l’érysipèle) dans un contexte de grosse jambe rouge (selon les caractéristiques cliniques et l’orientation diagnostique)","q":"Quelle est la rentabilité des hémocultures et des prélèvements de porte d'entrée dans le diagnostic microbiologique de l'érysipèle ?","a":"<ul><li>Les <strong>hémocultures</strong> ont une faible rentabilité, avec moins de 5 % de positivité.</li><li>Le <strong>prélèvement de la porte d'entrée</strong> est utile dans les formes graves, mais son interprétation est délicate en raison du risque de colonisation par des bactéries non responsables (ex: bacilles à Gram négatif).</li></ul>"},{"i":"c3dec404034d","n":350,"o":"350-5","u":"Examens complémentaires","t":"Connaître la pertinence des examens complémentaires (de l’érysipèle) dans un contexte de grosse jambe rouge (selon les caractéristiques cliniques et l’orientation diagnostique)","q":"Quelle est la valeur des D-dimères dans le diagnostic différentiel entre érysipèle et thrombose veineuse profonde ?","a":"<p>Les D-dimères sont souvent <strong>élevés</strong> en cas d'érysipèle. Ils ne permettent donc pas à eux seuls d'écarter ou d'affirmer le diagnostic de thrombose veineuse profonde (TVP). Seul l'<strong>écho-Doppler veineux</strong> permet de trancher entre ces deux diagnostics.</p>"},{"i":"1233f00581bb","n":350,"o":"350-6","u":"Contenu multimédia","t":"Photographie d’un érysipèle de jambe typique","q":"Quelles sont les caractéristiques topographiques et évolutives d'un érysipèle de jambe typique ?","a":"<p>L'érysipèle de jambe typique réalise une atteinte <strong>unilatérale</strong> d'un membre inférieur, avec une <strong>extension rapide</strong> (nécessitant de marquer les contours au feutre pour suivre l'évolution).</p>"},{"i":"7115a71b9476","n":350,"o":"350-6","u":"Contenu multimédia","t":"Photographie d’un érysipèle de jambe typique","q":"Quels sont les signes cliniques non graves parfois associés au placard d'érysipèle ?","a":"<ul><li>Un <strong>bourrelet périphérique</strong> (limite nette surélevée, surtout au visage)</li><li>Un <strong>décollement bulleux superficiel</strong></li><li>Un <strong>purpura localisé</strong> sur le placard</li></ul>"},{"i":"da4d7ab5265f","n":350,"o":"350-6","u":"Contenu multimédia","t":"Photographie d’un érysipèle de jambe typique","q":"Quels signes cliniques ne doivent PAS être présents dans un érysipèle de jambe simple et orienteraient vers une dermohypodermite nécrosante ?","a":"<ul><li>Une <strong>nécrose</strong> (plaques noirâtres, zones livedoïdes)</li><li>Des <strong>bulles hémorragiques</strong></li><li>Des <strong>taches cyaniques ou livedo</strong></li></ul>"},{"i":"ed6f4e08b527","n":350,"o":"350-6","u":"Contenu multimédia","t":"Photographie d’un érysipèle de jambe typique","q":"Quelle est la sémiologie clinique d'un érysipèle de jambe typique à l'inspection d'un placard inflammatoire ?","a":"<p>Un érysipèle de jambe typique se présente comme un placard <strong>érythémateux rouge vif</strong>, <strong>chaud</strong>, <strong>bien limité</strong>, <strong>œdémateux</strong> et <strong>douloureux</strong>.</p>"},{"i":"f4f23d7df80a","n":350,"o":"350-6","u":"Contenu multimédia","t":"Photographie d’un érysipèle de jambe typique","q":"Quel élément clé est souvent retrouvé en aval d'un placard d'érysipèle de jambe ?","a":"<p>Une <strong>porte d'entrée visible</strong> est souvent retrouvée en aval du placard, comme un <strong>intertrigo inter-orteils</strong> ou un ulcère.</p>"},{"i":"70aefd414f52","n":350,"o":"350-7","u":"Diagnostic positif","t":"Connaître l’algorithme diagnostique","q":"Quel diagnostic doit être évoqué en priorité devant une grosse jambe rouge aiguë fébrile et non compliquée ?","a":"<p>Devant une grosse jambe rouge <strong>aiguë et fébrile</strong>, le diagnostic à évoquer en priorité est l'<strong>érysipèle</strong>, jusqu'à preuve du contraire.</p>"},{"i":"7f4f01b09eaf","n":350,"o":"350-7","u":"Diagnostic positif","t":"Connaître l’algorithme diagnostique","q":"Quels diagnostics sont à considérer en dehors d'un contexte de grosse jambe rouge aiguë fébrile ?","a":"<ul><li>En cas de grosse jambe rouge <strong>subaiguë fébrile</strong> : autres <strong>dermohypodermites infectieuses</strong>.</li><li>En cas de grosse jambe rouge <strong>non fébrile</strong> : <strong>insuffisance veineuse</strong>, <strong>pied diabétique</strong>.</li><li>En cas de grosse jambe rouge non fébrile associée à d'autres lésions élémentaires : <strong>eczéma</strong>.</li></ul>"},{"i":"a504d4e078a6","n":350,"o":"350-7","u":"Diagnostic positif","t":"Connaître l’algorithme diagnostique","q":"Quand faut-il évoquer une fasciite nécrosante devant une grosse jambe rouge aiguë, et quelle est sa prise en charge ?","a":"<p>Une <strong>fasciite nécrosante</strong> doit être évoquée devant une grosse jambe rouge <strong>aiguë fébrile</strong> si elle s'accompagne de <strong>douleur intense</strong>, de <strong>sepsis</strong> et de <strong>nécrose cutanée</strong>. C'est une <strong>urgence médico-chirurgicale</strong>.</p>"},{"i":"b516e46de4e2","n":350,"o":"350-7","u":"Diagnostic positif","t":"Connaître l’algorithme diagnostique","q":"Quelle est la première étape de l'algorithme diagnostique face à une grosse jambe rouge aiguë ?","a":"<p>Face à une grosse jambe rouge, la première étape est de se poser deux questions fondamentales : y a-t-il de la <strong>fièvre</strong> et l'évolution est-elle <strong>aiguë</strong> ? Il faut également rechercher d'emblée des <strong>signes de gravité</strong>.</p>"},{"i":"edb25b2a2b4d","n":350,"o":"350-7","u":"Diagnostic positif","t":"Connaître l’algorithme diagnostique","q":"Citez deux diagnostics différentiels importants à évoquer devant une grosse jambe rouge aiguë, en dehors des infections cutanées.","a":"<p>Deux diagnostics différentiels importants devant une grosse jambe rouge aiguë sont la <strong>dermite de stase</strong> et la <strong>thrombose veineuse profonde (TVP)</strong>.</p>"},{"i":"174647e68ff2","n":350,"o":"350-8","u":"Identifier une urgence","t":"Connaître l’attitude et la prise en charge clinique dans les situations d’urgence","q":"Comment doit être prise en charge une dermohypodermite ou fasciite nécrosante, qui est une urgence vitale de la grosse jambe rouge aiguë ?","a":"<p>La prise en charge est une urgence vitale et doit être triple :</p><ul><li><strong>Réanimation</strong> en unité de soins intensifs (USI) pour suppléer les défaillances d'organes.</li><li><strong>Chirurgie précoce</strong> et répétée : mise à plat, excision des tissus nécrosés, reprises quotidiennes. L'imagerie ne doit jamais retarder ce geste.</li><li><strong>Antibiothérapie IV à forte dose</strong> pendant <strong>14 à 21 jours</strong>. La combinaison dépend de la localisation et des facteurs de risque (ex: <strong>Augmentin + clindamycine</strong> pour les membres, <strong>pipéracilline-tazobactam ou imipénème</strong> pour les formes abdomino-périnéales).</li></ul><p>Les <strong>AINS doivent être arrêtés</strong>.</p>"},{"i":"a158a04f02a5","n":350,"o":"350-8","u":"Identifier une urgence","t":"Connaître l’attitude et la prise en charge clinique dans les situations d’urgence","q":"Dans le contexte d'une grosse jambe rouge aiguë (GJRA), quels sont les critères d'hospitalisation à prendre en compte ?","a":"<p>L'hospitalisation est requise si un traitement parentéral et/ou une surveillance rapprochée sont nécessaires. Les critères incluent :</p><ul><li>Un <strong>doute diagnostique</strong>.</li><li>Des <strong>signes locaux et/ou généraux marqués</strong>.</li><li>Un <strong>risque de complications</strong> lié au terrain (<strong>âge > 75 ans ou < 1 an</strong>, <strong>obésité morbide</strong>, comorbidités à risque de décompensation).</li><li>Un <strong>contexte social</strong> rendant le repos et le suivi difficiles en ambulatoire.</li><li>L'<strong>absence d'amélioration à 24-72 h</strong> ou une <strong>extension sous traitement</strong>.</li></ul>"},{"i":"d70063036109","n":350,"o":"350-8","u":"Identifier une urgence","t":"Connaître l’attitude et la prise en charge clinique dans les situations d’urgence","q":"Quelles sont les mesures générales et l'antibiothérapie de première intention pour un érysipèle non compliqué, en cas de grosse jambe rouge aiguë ?","a":"<p>Les mesures générales comprennent :</p><ul><li><strong>Repos au lit</strong>, jambe surélevée.</li><li><strong>Antalgiques</strong> (<strong>paracétamol</strong>) en évitant les AINS et les corticoïdes.</li><li>Anticoagulation préventive (<strong>HBPM/héparine calcique</strong>) uniquement en présence de facteurs de risque de MTEV.</li><li>Vérification et mise à jour de la <strong>vaccination antitétanique</strong>.</li><li>Traitement de la <strong>porte d'entrée</strong>.</li></ul><p>L'antibiothérapie de première intention est l'<strong>amoxicilline</strong> pendant <strong>7 jours</strong>, par voie <strong>per os</strong> si ambulatoire, ou <strong>IV</strong> avec relais per os si hospitalisation. En cas d'allergie à la pénicilline, la <strong>pristinamycine</strong> ou la <strong>clindamycine</strong> sont utilisées. Les antibiotiques locaux sont proscrits.</p>"},{"i":"20df630dd482","n":350,"o":"350-9","u":"Identifier une urgence","t":"Savoir évoquer le diagnostic d’une fasciite nécrosante","q":"Quels sont les signes cliniques locaux spécifiques à rechercher pour évoquer une fasciite nécrosante ?","a":"<p>Les signes locaux dits 'drapeaux rouges' de la fasciite nécrosante incluent :</p><ul><li>Une <strong>douleur spontanée intense</strong>, disproportionnée par rapport aux lésions cutanées visibles, qui dépasse les zones inflammatoires et <strong>non soulagée par les antalgiques de palier 1-2</strong>.</li><li>Des signes de nécrose cutanée : <strong>pâleur</strong>, <strong>plaques noirâtres</strong>, <strong>zones livedoïdes</strong>, <strong>taches cyaniques</strong>.</li><li>Des <strong>bulles hémorragiques ou séro-hématiques</strong>, et des <strong>écoulements fétides</strong>.</li><li>Une <strong>hypoesthésie voire anesthésie</strong> de la zone (appelée 'anesthésie douloureuse'), et parfois une <strong>crépitation</strong> (suggérant des anaérobies).</li><li>Une <strong>extension rapide</strong> de l'induration au-delà de l'érythème et ce, malgré une antibiothérapie bien conduite.</li></ul>"},{"i":"32d326ba213b","n":350,"o":"350-9","u":"Identifier une urgence","t":"Savoir évoquer le diagnostic d’une fasciite nécrosante","q":"Quels sont les 'faux amis' qui ne doivent pas faire retenir le diagnostic de fasciite nécrosante à eux seuls ?","a":"<p>Les 'faux amis' sont des signes qui peuvent évoquer la gravité mais qui, à eux seuls, ne sont pas spécifiques de la fasciite nécrosante et peuvent exister dans un érysipèle non compliqué. Il s'agit des <strong>phlyctènes</strong>, du <strong>décollement bulleux</strong> et du <strong>purpura</strong>.</p>"},{"i":"4bb04dd78d9b","n":350,"o":"350-9","u":"Identifier une urgence","t":"Savoir évoquer le diagnostic d’une fasciite nécrosante","q":"Quels sont les signes généraux et les facteurs de risque à prendre en compte pour une suspicion de fasciite nécrosante ?","a":"<p>Les signes généraux de la fasciite nécrosante sont ceux d'un <strong>sepsis</strong> :</p><ul><li><strong>Fièvre élevée ou hypothermie</strong>, frissons.</li><li>Confusion/désorientation, tachypnée, tachycardie, hypotension, oligurie, pâleur.</li><li>Un score <strong>qSOFA ≥ 2</strong> (Fréquence Respiratoire ≥ 22/min, Pression Artérielle Systolique ≤ 100 mmHg, Glasgow < 15) est évocateur.</li></ul><p>Les facteurs de risque pour la fasciite nécrosante (en dehors des facteurs de risque d'érysipèle) incluent : <strong>âge &gt; 60 ans</strong>, <strong>diabète</strong>, <strong>immunodépression</strong>, <strong>toxicomanie IV</strong>, <strong>artériopathie oblitérante des membres inférieurs (AOMI)</strong>, et la prise d'<strong>AINS</strong>.</p>"},{"i":"c324ac464eec","n":350,"o":"350-9","u":"Identifier une urgence","t":"Savoir évoquer le diagnostic d’une fasciite nécrosante","q":"Comment définir la fasciite nécrosante et en quoi est-ce une urgence vitale ?","a":"<p>La fasciite nécrosante (ou dermohypodermite bactérienne nécrosante) est une infection bactérienne grave des tissus mous, <strong>100 fois plus rare</strong> que l'érysipèle. Elle se caractérise par une <strong>nécrose rapide et progressive</strong> de la profondeur vers la superficie (fascias, derme, hypoderme), ce qui en fait une <strong>urgence médico-chirurgicale vitale</strong>.</p>"},{"i":"f324f5f40181","n":350,"o":"350-9","u":"Identifier une urgence","t":"Savoir évoquer le diagnostic d’une fasciite nécrosante","q":"Quelle est la ou les bactéries le(s) plus souvent impliquée(s) dans la fasciite nécrosante et quel est le risque associé ?","a":"<p>Le germe le plus souvent identifié de manière isolée est le <strong>Streptocoque du groupe A (SGA)</strong>. Cependant, la fasciite nécrosante est <strong>polymicrobienne dans 70 à 80 % des cas</strong>, souvent avec la présence de <strong><em>Staphylococcus aureus</em></strong> en association. Certaines souches bactériennes peuvent être productrices de toxines, exposant au risque de <strong>choc toxinique</strong>.</p>"}]};